const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path');
(async()=>{const b=await chromium.launch({args:['--no-sandbox']});try{const p=await b.newPage({viewport:{width:390,height:1000}}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.clock.install();await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.evaluate(()=>{window.speak=()=>Promise.resolve();window.tone=()=>{}});await p.click('#learningTab');await p.evaluate(()=>{const a=DEUTSCH_ADAPTIVE;profileStorage.removeItem(a.key);for(const s of a.stages){if(s.cards.length<4||s.cards.length>6)throw Error('Batch size '+s.id);for(const c of s.cards){if(!RECORDED_AUDIO[c.de.toLowerCase().replace(/[.!?]/g,'')])throw Error('Missing whole recording '+c.de);if(!a.art(c))throw Error('Missing art '+c.de);const opts=a.optionsFor(c);if(opts.length<2||opts.some(o=>a.category(o)!==a.category(c)))throw Error('Mixed option categories')}}a.start();if(document.querySelectorAll('.al-study-grid .course-card').length!==5)throw Error('Missing illustrated overview');if(document.querySelector('#alContinue').textContent!=='Перевір себе')throw Error('Wrong label');document.querySelector('#alContinue').click();const s=a.snapshot();if(s.queue.map(q=>q.type).join(',')!==['ua','de','listen','write','speak'].flatMap(t=>Array(5).fill(t)).join(','))throw Error('Wrong round order');a.answer(s.queue[0].c.ua);a.answer('duplicate')});await p.clock.runFor(2100);if(await p.evaluate(()=>DEUTSCH_ADAPTIVE.snapshot().index)!==1)throw Error('No automatic advancement');await p.evaluate(()=>DEUTSCH_ADAPTIVE.answer('wrong'));await p.clock.runFor(8000);if(await p.evaluate(()=>DEUTSCH_ADAPTIVE.snapshot().index)!==1)throw Error('Wrong answer advanced');await p.click('#alNext');
await p.evaluate(()=>{const a=DEUTSCH_ADAPTIVE;let s=a.snapshot();while(s.index<10){const q=s.queue[s.index];a.answer(q.type==='ua'?q.c.ua:q.c.de);document.querySelector('#alNext').click()}if(s.queue[s.index].type!=='listen')throw Error('Not listening round');if(document.querySelector('#learningView').textContent.includes(s.queue[s.index].c.de)||document.querySelector('#learningView [lang="de"]'))throw Error('Listening answer leaked');for(let i=0;i<5;i++){a.answer(s.queue[s.index].c.ua);document.querySelector('#alNext').click()}if(s.queue[s.index].type!=='write'||!document.querySelector('#alForm'))throw Error('Writing missing');const before=DEUTSCH_PROGRESS.snapshot().answers;a.skip();if(DEUTSCH_PROGRESS.snapshot().answers!==before||s.skipped!==1)throw Error('Skip counted as failed answer');while(s.index<20){a.answer(s.queue[s.index].c.de);document.querySelector('#alNext').click()}if(!document.querySelector('#alMic'))throw Error('Microphone stage missing');class R{constructor(){window.testAdaptiveMic=this}start(){}abort(){}}window.SpeechRecognition=R;document.querySelector('#alMic').disabled=false;document.querySelector('#alMic').click();testAdaptiveMic.onresult({results:[[{transcript:'wrong recognition'}]]});if(s.locked||document.querySelector('#alVoiceWrong').hidden)throw Error('ASR mismatch graded without confirmation');document.querySelector('#alVoiceWrong').click();if(s.results.at(-1).ok!==false)throw Error('ASR confirmation not graded');document.querySelector('#alNext').click();document.querySelector('#alMic').click();const q=s.queue[s.index];testAdaptiveMic.onresult({results:[[{transcript:q.c.de}]]});if(!s.results.at(-1).ok)throw Error('Correct speech rejected');document.querySelector('#alNext').click();while(s.index<s.queue.length)a.skip();if(!s.finished||!document.querySelector('#alAgain svg')||!document.querySelector('#alMistakes svg')||!document.querySelector('#alMore svg'))throw Error('Summary actions missing');const failed=s.results.filter(r=>!r.ok||r.skipped).length;document.querySelector('#alMistakes').click();if(a.snapshot().queue.length!==failed)throw Error('Mistake retry includes unrelated tasks');while(!a.snapshot().finished)a.skip();document.querySelector('#alAgain').click();if(!a.snapshot().queue.length)throw Error('Repeat all missing');setMode('home');setMode('learning');if(a.plan().n!==1)throw Error('Completed batch does not advance');a.start();document.querySelector('#alContinue').click();while(!a.snapshot().finished)a.skip();document.querySelector('#alMore').click();if(a.snapshot().stageId!=='ich-du')throw Error('Cannot continue to next batch');setMode('home');if(a.snapshot())throw Error('Navigation did not cancel session')});
await p.clock.runFor(5000);await p.reload();await p.click('#learningTab');if(await p.evaluate(()=>DEUTSCH_ADAPTIVE.plan().n)!==2)throw Error('Progress lost');await p.evaluate(()=>{const a=DEUTSCH_ADAPTIVE,saved=profileStorage.getItem(a.key),cards={};a.stages[0].cards.forEach(c=>cards[c.id]={success:3,bad:0,step:1,due:Date.now()+86400000});profileStorage.setItem(a.key,JSON.stringify({version:1,cards}));const p=a.plan();if(p.n!==1||!p.d.sessions['people-five'].migrated||p.d.cards.ich.success!==3)throw Error('Legacy progress migration failed');profileStorage.setItem(a.key,saved)});for(const width of [320,390,768,1280]){await p.setViewportSize({width,height:1000});if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Overflow '+width)}await p.click('#profileButton');await p.fill('#profileAddInput','Carousel child');await Promise.all([p.waitForEvent('load'),p.click('#profileAddForm button')]);await p.click('#learningTab');if(!await p.evaluate(()=>Object.keys(DEUTSCH_ADAPTIVE.plan().d.cards).length===0&&DEUTSCH_ADAPTIVE.plan().n===0))throw Error('Profile isolation failed');if(errors.length)throw Error(errors.join(';'));console.log('PASS five ordered skill rounds, 4–6 item batches, original audio/art, hidden listening answer, auto-next, held errors, neutral skips, ASR confirmation, icon actions, retry scope, persistence and profiles');}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
